<script setup>
import{ref,onMounted,computed}from'vue';import{useRoute}from'vue-router';import{api}from'../services/api.js';import{can}from'../stores/auth.js';import UiState from'../components/UiState.vue';import BaseModal from'../components/BaseModal.vue';import ConfirmDialog from'../components/ConfirmDialog.vue';import ArticleSalesTab from'../components/ArticleSalesTab.vue';import CompostGroupingTab from'../components/CompostGroupingTab.vue'
const route=useRoute(),today=new Date().toISOString().slice(0,10),defaultFrom=`${new Date().getFullYear()-6}-01-01`;const tab=ref('sales'),from=ref(String(route.query.from||defaultFrom)),to=ref(String(route.query.to||today)),article=ref(String(route.query.article||'')),sales=ref([]),imports=ref([]),selected=ref(null),loading=ref(false),processing=ref(false),error=ref(''),notice=ref(''),file=ref(null),dragging=ref(false),editOpen=ref(false),editing=ref(null),confirmOpen=ref(false),confirmError=ref(''),onlyIssues=ref(false),clientFilter=ref(''),noteFilter=ref('')
const money=value=>new Intl.NumberFormat('ca-ES',{style:'currency',currency:'EUR'}).format(Number(value||0)),quantity=value=>new Intl.NumberFormat('ca-ES',{maximumFractionDigits:4}).format(Number(value||0)),json=value=>Array.isArray(value)?value:(value?JSON.parse(value):[])
const filteredRows=computed(()=>selected.value?.rows?.filter(r=>(!onlyIssues.value||json(r.warnings).length)&&(!clientFilter.value||r.client_name?.toLowerCase().includes(clientFilter.value.toLowerCase()))&&(!noteFilter.value||r.delivery_note_number?.toLowerCase().includes(noteFilter.value.toLowerCase())))||[])
async function loadSales(){loading.value=true;error.value='';try{sales.value=await api.get(`/sales/clients?from=${from.value}&to=${to.value}&article=${encodeURIComponent(article.value)}`)}catch(e){error.value=e.message}finally{loading.value=false}}
async function loadImports(reportError=true){try{imports.value=await api.get('/imports');return true}catch(e){if(reportError)error.value=e.message;return false}}
function choose(event){const chosen=event.target.files?.[0]||event.dataTransfer?.files?.[0];dragging.value=false;if(chosen)file.value=chosen}
async function upload(){if(!file.value)return;processing.value=true;error.value='';notice.value='';try{const data=new FormData();data.append('file',file.value);selected.value=await api.post('/imports/delivery-notes/preview',data);tab.value='preview';notice.value='PDF processat correctament. Reviseu les dades abans de confirmar.';file.value=null;await loadImports(false)}catch(e){if(e.code==='IMPORT_EXISTS'&&e.details?.importId){await openImport(e.details.importId);error.value='';notice.value='Aquest PDF ja estava importat. S’ha obert la importació existent.';file.value=null;await loadImports(false)}else error.value=e.message}finally{processing.value=false}}
async function openImport(id){loading.value=true;try{selected.value=await api.get('/imports/'+id);tab.value='preview'}catch(e){error.value=e.message}finally{loading.value=false}}
function edit(row){editing.value={id:row.id,deliveryNoteNumber:row.delivery_note_number,date:row.delivery_date?.slice(0,10),productCode:row.product_code,concept:row.concept,quantity:row.quantity,unitPrice:row.unit_price,taxableBase:row.taxable_base,vatAmount:row.vat_amount,totalAmount:row.total_amount,vehiclePlate:row.vehicle_plate||'',trailerPlate:row.trailer_plate||''};editOpen.value=true}
async function saveRow(){selected.value=await api.patch(`/imports/${selected.value.id}/rows/${editing.value.id}`,editing.value);editOpen.value=false}
function openConfirm(){confirmError.value='';confirmOpen.value=true}
async function confirmImport(){if(processing.value)return;processing.value=true;confirmError.value='';error.value='';try{selected.value=await api.post(`/imports/${selected.value.id}/confirm`,{});confirmOpen.value=false;notice.value=`Importació completada: ${selected.value.confirmed_row_count} línies noves, ${selected.value.updated_row_count||0} preus actualitzats i ${selected.value.discarded_row_count} duplicats descartats.`;await Promise.all([loadImports(false),loadSales()])}catch(e){confirmError.value=e.message}finally{processing.value=false}}
onMounted(()=>Promise.all([loadSales(),loadImports()]))
</script>
<template>
 <div class="tabs" role="tablist"><button :class="{active:tab==='sales'}" @click="tab='sales'">Vendes per client</button><button :class="{active:tab==='articles'}" @click="tab='articles'">Vendes per articles</button><button :class="{active:tab==='compost'}" @click="tab='compost'">Classificació articles</button><button :class="{active:tab==='imports'}" @click="tab='imports'">Importacions</button><button v-if="selected" :class="{active:tab==='preview'}" @click="tab='preview'">Revisió #{{selected.id}}</button></div>
 <div v-if="error" class="alert error" role="alert">{{error}}</div>
 <div v-if="notice" class="alert success" role="status">{{notice}}</div>
 <section v-if="tab==='sales'">
  <form class="card filters sales-filters" @submit.prevent="loadSales"><label>Des de<input v-model="from" type="date" required></label><label>Fins a<input v-model="to" type="date" required></label><label class="article-search">Article<input v-model="article" type="search" placeholder="Codi o nom de l’article"></label><button class="button primary">Consultar</button></form>
  <UiState :loading="loading" :empty="!sales.length" empty-text="No hi ha vendes confirmades amb aquests filtres."><div class="table-wrap"><table><thead><tr><th>Client</th><th>Albarans</th><th>Línies</th><th>Quantitat</th><th>Base</th><th>IVA</th><th>Total</th><th></th></tr></thead><tbody><tr v-for="row in sales" :key="row.client_code" class="clickable-row"><td data-label="Client"><strong>{{row.client_name}}</strong><small>{{row.client_code}}</small></td><td data-label="Albarans">{{row.delivery_note_count}}</td><td data-label="Línies">{{row.line_count}}</td><td data-label="Quantitat"><strong>{{quantity(row.quantity)}}</strong></td><td data-label="Base">{{money(row.taxable_base)}}</td><td data-label="IVA">{{money(row.vat_amount)}}</td><td data-label="Total"><strong>{{money(row.total_amount)}}</strong></td><td><RouterLink class="button secondary compact" :to="{name:'client-sales-detail',params:{clientCode:row.client_code},query:{from,to,article}}">Veure historial</RouterLink></td></tr></tbody></table></div></UiState>
 </section>
 <ArticleSalesTab v-else-if="tab==='articles'"/>
 <CompostGroupingTab v-else-if="tab==='compost'"/>
 <section v-else-if="tab==='imports'">
  <div v-if="can('sales_clients.manage')" class="card upload-card"><label class="drop-zone" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave="dragging=false" @drop.prevent="choose"><input class="sr-only" type="file" accept="application/pdf,.pdf" @change="choose"><span class="empty-icon">⇧</span><strong>{{file?.name||'Arrossegueu un PDF o feu clic per seleccionar-lo'}}</strong><small>Màxim configurat: PDF amb capa de text</small></label><button class="button primary" :disabled="!file||processing" @click="upload">{{processing?'Processant totes les pàgines…':'Previsualitzar importació'}}</button></div>
  <UiState :empty="!imports.length" empty-text="Encara no hi ha importacions."><div class="table-wrap"><table><thead><tr><th>Fitxer</th><th>Data</th><th>Estat</th><th>Clients</th><th>Línies</th><th>Total</th><th></th></tr></thead><tbody><tr v-for="item in imports" :key="item.id"><td data-label="Fitxer">{{item.original_filename}}</td><td data-label="Data">{{new Date(item.created_at).toLocaleString('ca-ES')}}</td><td data-label="Estat"><span class="badge" :class="item.status==='completed'?'success':'neutral'">{{item.status}}</span></td><td data-label="Clients">{{item.client_count}}</td><td data-label="Línies">{{item.row_count}}</td><td data-label="Total">{{money(item.total_amount)}}</td><td><button class="button secondary compact" @click="openImport(item.id)">Consultar</button></td></tr></tbody></table></div></UiState>
 </section>
 <section v-else-if="selected" class="preview">
  <div class="summary-grid"><article class="card"><small>Empresa</small><strong>{{selected.detected_company}}</strong></article><article class="card"><small>Pàgines</small><strong>{{selected.page_count}}</strong></article><article class="card"><small>Clients</small><strong>{{selected.client_count}}</strong></article><article class="card"><small>Línies</small><strong>{{selected.row_count}}</strong></article><article v-if="selected.status==='completed'" class="card"><small>Confirmades</small><strong>{{selected.confirmed_row_count}}</strong></article><article v-if="selected.status==='completed'" class="card"><small>Duplicats descartats</small><strong>{{selected.discarded_row_count}}</strong></article><article v-if="selected.status==='completed'" class="card"><small>Preus actualitzats</small><strong>{{selected.updated_row_count||0}}</strong></article><article class="card"><small>Base</small><strong>{{money(selected.taxable_base_total)}}</strong></article><article class="card"><small>IVA</small><strong>{{money(selected.vat_total)}}</strong></article><article class="card"><small>Total</small><strong>{{money(selected.total_amount)}}</strong></article><article class="card"><small>Incidències</small><strong>{{json(selected.warnings).length}}</strong></article></div>
  <details v-if="json(selected.warnings).length" class="alert warning import-issues" open>
   <summary><strong>Cal revisar aquestes incidències:</strong><span>{{json(selected.warnings).length}}</span></summary>
   <ul><li v-for="warning in json(selected.warnings)">{{warning.message||warning}}</li></ul>
  </details>
  <div class="toolbar preview-tools"><div class="search"><input v-model="clientFilter" placeholder="Filtrar client"><input v-model="noteFilter" placeholder="Filtrar albarà"></div><label class="check"><input v-model="onlyIssues" type="checkbox"> Només incidències</label><button v-if="selected.status==='pending_review'&&can('sales_clients.manage')" class="button primary" @click="openConfirm">Confirmar importació</button></div>
  <div class="table-wrap"><table class="preview-table"><thead><tr><th>Pàg.</th><th>Client</th><th>Albarà/data</th><th>Producte/concepte</th><th>Quantitat × preu</th><th>Base + IVA</th><th>Total</th><th>Revisió</th></tr></thead><tbody><tr v-for="row in filteredRows" :key="row.id" :class="{issue:json(row.warnings).length}"><td data-label="Pàgina">{{row.source_page}}</td><td data-label="Client">{{row.client_name}}<small>{{row.client_code}}</small></td><td data-label="Albarà"><strong>{{row.delivery_note_number}}</strong><small>{{row.delivery_date?.slice(0,10)}}</small></td><td data-label="Producte">{{row.product_code}} — {{row.concept}}<small v-if="row.waste_code">LER {{row.waste_code}}</small></td><td data-label="Quantitat">{{row.quantity}} × {{row.unit_price}}</td><td data-label="Base">{{money(row.taxable_base)}} + {{money(row.vat_amount)}}</td><td data-label="Total">{{money(row.total_amount)}}</td><td><div v-for="warning in json(row.warnings)" class="warning-text">{{warning}}</div><button v-if="selected.status==='pending_review'&&can('sales_clients.manage')" class="button secondary compact" @click="edit(row)">Editar</button></td></tr></tbody></table></div>
 </section>
 <BaseModal :open="editOpen" title="Corregir línia" @close="editOpen=false"><form v-if="editing" id="row-form" class="form-grid" @submit.prevent="saveRow"><label>Albarà<input v-model="editing.deliveryNoteNumber" required></label><label>Data<input v-model="editing.date" type="date"></label><label>Producte<input v-model="editing.productCode"></label><label>Quantitat<input v-model="editing.quantity" inputmode="decimal"></label><label class="full">Concepte<textarea v-model="editing.concept"></textarea></label><label>Preu unitari<input v-model="editing.unitPrice" inputmode="decimal"></label><label>Base imposable<input v-model="editing.taxableBase" inputmode="decimal"></label><label>IVA<input v-model="editing.vatAmount" inputmode="decimal"></label><label>Total<input v-model="editing.totalAmount" inputmode="decimal"></label><label>Matrícula<input v-model="editing.vehiclePlate"></label><label>Remolc<input v-model="editing.trailerPlate"></label></form><template #actions><button class="button secondary" @click="editOpen=false">Cancel·lar</button><button form="row-form" class="button primary">Desar correcció</button></template></BaseModal>
 <ConfirmDialog :open="confirmOpen" title="Confirmar importació" message="Les línies passaran a formar part de les vendes. Aquesta acció quedarà auditada." :busy="processing" :error="confirmError" busy-text="Confirmant importació…" @cancel="confirmOpen=false" @confirm="confirmImport"/>
</template>
